            status: "unconfigured",
            source: "local",
            sourceLabel: "\u672C\u673A Codex \u68C0\u6D4B",
            windows: [],
            balance: "",
            error: "\u672C\u673A Codex auth.json \u4EC5\u542B API Key\uFF1B\u8BA2\u9605\u7A97\u53E3\u9700\u6267\u884C codex login",
            checkedAt: Date.now()
